import unittest

from limits import clamp


class ClampTests(unittest.TestCase):
    def test_returns_value_inside_range(self):
        self.assertEqual(clamp(4, 1, 8), 4)

    def test_returns_minimum_below_range(self):
        self.assertEqual(clamp(-2, 1, 8), 1)

    def test_returns_maximum_above_range(self):
        self.assertEqual(clamp(10, 1, 8), 8)

    def test_preserves_range_boundaries(self):
        for value in (1, 8):
            with self.subTest(value=value):
                self.assertEqual(clamp(value, 1, 8), value)

    def test_accepts_single_value_range(self):
        for value in (0, 3, 10):
            with self.subTest(value=value):
                self.assertEqual(clamp(value, 3, 3), 3)

    def test_supports_fractional_values(self):
        self.assertEqual(clamp(1.5, 1.0, 2.0), 1.5)

    def test_rejects_reversed_range(self):
        with self.assertRaises(ValueError):
            clamp(4, 8, 1)


if __name__ == "__main__":
    unittest.main()
